div.script:
 (function () {
  const container = document.getElementById(
    "halloween-video-preview"
  );

  if (!container || container.dataset.initialized) return;
  container.dataset.initialized = "true";

  const playerContainer = container.querySelector(
    ".halloween-video__player"
  );
  const playButton = container.querySelector(
    ".halloween-video__play"
  );

  const videoId = "xx5g8glmtb";
  let fullVideoStarted = false;

  function createPlayer(isFullVideo) {
    const player = document.createElement("wistia-player");

    player.setAttribute("media-id", videoId);
    player.setAttribute("aspect", "2.4");
    player.setAttribute("playsinline", "");
    player.setAttribute("big-play-button", "false");

    if (isFullVideo) {
      player.setAttribute("autoplay", "");
      player.setAttribute("controls-visible-on-load", "true");
      player.setAttribute("playbar", "true");
      player.setAttribute("time", "0");
      player.removeAttribute("muted");
    } else {
      player.setAttribute("autoplay", "");
      player.setAttribute("muted", "");
      player.setAttribute("silent-auto-play", "true");
      player.setAttribute("controls-visible-on-load", "false");
      player.setAttribute("playbar", "false");
      player.setAttribute("time", "3");
    }

    return player;
  }

  // Keep the DAM image visible for 2.5 seconds.
  window.setTimeout(function () {
    if (fullVideoStarted) return;

    playerContainer.replaceChildren(createPlayer(false));
    container.classList.add("is-ready");
  }, 2500);

  playButton.addEventListener("click", function () {
    if (fullVideoStarted) return;

    fullVideoStarted = true;

    playerContainer.replaceChildren(createPlayer(true));
    container.classList.add("is-ready", "is-playing");
  });
})();

pre.code:
// Install the C# / .NET helper library from twilio.com/docs/csharp/install
using System;
using Twilio;
using Twilio.Rest.Api.V2010.Account;

class Program
{
    static void Main(string[] args)
    {
        // Find your Account SID and Auth Token at twilio.com/console
        // and set the environment variables. See http://twil.io/secure
        string accountSid = Environment.GetEnvironmentVariable("TWILIO_ACCOUNT_SID");
        string authToken = Environment.GetEnvironmentVariable("TWILIO_AUTH_TOKEN");

        TwilioClient.Init(accountSid, authToken);

        var message = MessageResource.Create(
            body: "Hi there",
            from: new Twilio.Types.PhoneNumber("+15017122661"),
            to: new Twilio.Types.PhoneNumber("+15558675310")
        );

        Console.WriteLine(message.Sid);
    }
}

// Install the Java helper library from twilio.com/docs/java/install

import com.twilio.Twilio;
import com.twilio.rest.api.v2010.account.Message;
import com.twilio.type.PhoneNumber;

public class Example {
    // Find your Account SID and Auth Token at twilio.com/console
    // and set the environment variables. See http://twil.io/secure
    public static final String ACCOUNT_SID = System.getenv("TWILIO_ACCOUNT_SID");
    public static final String AUTH_TOKEN = System.getenv("TWILIO_AUTH_TOKEN");

    public static void main(String[] args) {
        Twilio.init(ACCOUNT_SID, AUTH_TOKEN);
        Message message = Message.creator(
                new com.twilio.type.PhoneNumber("+15558675310"),
                new com.twilio.type.PhoneNumber("+15017122661"),
                "Hi there")
            .create();

        System.out.println(message.getSid());
    }
}

// Download the helper library from https://www.twilio.com/docs/node/install
// Find your Account SID and Auth Token at twilio.com/console
// and set the environment variables. See http://twil.io/secure
const accountSid = process.env.TWILIO_ACCOUNT_SID;
const authToken = process.env.TWILIO_AUTH_TOKEN;
const client = require('twilio')(accountSid, authToken);

client.messages
      .create({body: 'Hi there', from: '+15017122661', to: '+15558675310'})
      .then(message => console.log(message.sid));

body.script:
    analytics.addSourceMiddleware(({ payload, next, integrations }) => {
    const getCookie = function (name) {
    const value = "; " + document.cookie;
    const parts = value.split("; " + name + "=");
    if (parts.length === 2) return parts.pop().split(";").shift();
    };
    const event = payload.obj;
    const vwoUuid = getCookie("_vwo_uuid");
    switch (event.type) {
    case "track":
    case "page":
        payload.obj.properties.vwo_uuid = vwoUuid;
        break;
    case "identify":
        payload.obj.traits.vwo_uuid = vwoUuid;
        break;
    }
    next();
});

